pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor.code.length == 0);
        vm.deal(address(this), 1 ether);

        // grant a first-withdrawal bonus to actor (this triggers one payout of 100)
        vm.prank(address(this));
        c.getFirstWithdrawalBonus(actor);
        uint256 afterFirst = actor.balance;

