contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient) public {
        // Admissible domain: a plain externally-owned recipient (no code, not a precompile/zero)
        vm.assume(uint160(recipient) >= 0x100000);

        // Fund the contract with exactly the reward amount so the bonus flow succeeds
        vm.deal(address(c), 100);

        // Grant the first-withdrawal bonus; in the reference this pays 100 wei and zeroes the reward
        c.getFirstWithdrawalBonus(recipient);

        // Rule: any later withdrawReward(recipient) must SUCCEED — the reward was zeroed,
        // so only 0 wei is sent and require(success) holds even with an empty balance.
        bool ok;
        try c.withdrawReward(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

