pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker();
        attacker.setTarget(c);
    }

    function testFuzz_property(uint256 funding) public {
        // c must hold at least the 100-wei bonus so the (buggy) payout can succeed
        funding = bound(funding, 100, type(uint256).max / 2);
        vm.deal(address(c), funding);

        bool ok;
        // The attacker re-enters c.withdrawReward during the payout; with the lock
        // (reference) the re-entrant call reverts, making the bonus call revert.
        try c.getFirstWithdrawalBonus(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract ReentrantAttacker {
    C internal target;
    bool internal entered;

    function setTarget(C t) external { target = t; }

    receive() external payable {
        if (!entered) {
            entered = true;
            target.withdrawReward(address(this));
        }
    }
}

