pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        // First call always succeeds on both P and M (lock not yet engaged).
        bool ok1;
        try c.withdrawReward(actor) { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);

        // General rule: withdrawReward is re-invokable for ANY actor any number of
        // times, since the reentrancy lock is released after each completed call.
        bool ok2;
        try c.withdrawReward(actor) { ok2 = true; } catch { ok2 = false; }

        // Reference C: every sequential withdrawReward succeeds (ok2 == true).
        // Mutant M: the lock stays engaged, so this call reverts (ok2 == false).
        assertTrue(ok2, "withdrawReward must be invokable repeatedly");
    }
}

