pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address first, address second) public {
        vm.assume(first != second);
        vm.assume(first != address(c) && second != address(c));
        vm.assume(first.code.length == 0 && second.code.length == 0);

        // fund c so any reward withdrawal with nonzero amount could also pay out
        vm.deal(address(c), 1 ether);

        bool ok1;
        bool ok2;
        vm.prank(first);
        try c.withdrawReward(first) { ok1 = true; } catch { ok1 = false; }
        vm.prank(second);
        try c.withdrawReward(second) { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && ok2, "second withdrawReward must succeed: lock is always released after a call completes");
    }
}

