contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        // The recipient is this test contract, whose receive() always reverts,
        // so the external payout call inside withdrawReward fails.
        require(recipient == address(this), "recipient must be the test contract");

        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }

        // If the external payout to the recipient fails, withdrawReward must revert.
        // The mutant swallows the failure (no require(success)) and completes instead.
        assert(reverted);
    }

    receive() external payable {
        revert("recipient rejects ETH");
    }
}

